/// Generates into a zeroed `[0u8; 27]` buffer via [`ulidgen_r`] and returns
/// the first 26 bytes as a String.
pub fn ulid() -> String {
    let mut buf = [0u8; 27];
    ulidgen_r(&mut buf);
    String::from_utf8_lossy(&buf[..26]).into_owned()
